    numberField: true,
    decimalField: true,
    dateField: true,
    datetimeField: true,
    booleanField: true,
    picklistField: true,
    multiPicklistField: true,
    richTextField: true,
    attachmentField: true,
    groupField: true,
    jsonField: true,
    qrCodeField: true,
    userField: true,
    calculationField: true,
